import{z as s,x as o,o as E,c as l,q as r,j as A,D as a,d as c,s as t,S as n}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"GPU 调试","description":"","frontmatter":{"title":"GPU 调试","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gpu-debugging.md","filePath":"cs/gpu-debugging.md","lastUpdated":1791063341000}'),B={name:"cs/gpu-debugging.md"};function d(p,e,C,u,m,h){const i=o("Mermaid");return E(),l("div",null,[e[2]||(e[2]=r('<h1 id="gpu-调试" tabindex="-1">GPU 调试 <a class="header-anchor" href="#gpu-调试" aria-label="Permalink to &quot;GPU 调试&quot;">​</a></h1><div class="epigraph"><p>CPU 调试者信两件事：断点会停在原处，错误会立刻抛出；GPU 把两件都收走了——调试的第一步是承认这一点。</p><footer>—— 据 CUDA 工具链文档（cuda-gdb、compute-sanitizer）整理</footer></div><p><a href="/cs/gpu-profiling">上一课</a>把「慢」变成了证据；本课处理「错」。缺口的形态很具体：kernel 报错在几步之后才浮出、竞态只在特定 warp 交错时出现、printf 的顺序毫无意义——host 侧调试直觉在这三条上全部失灵。方法侧同样三条：cuda-gdb 的 warp 级视角、printf 的真实语义、compute-sanitizer 四件套。工具的名字不重要，重要的是每件工具对应哪一类「失灵」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三条失灵各有机制。第一，launch 是异步的（第一课的合同）：非法访存的错误码要等以后某次同步才返回，此时出错现场早已散场，栈不可追。第二，smem 没有一致性协议兜底（第四课的端口账）：CPU 上没出现竞态的代码搬到 GPU 上会出，因为缓存一致性协议在 CPU 上悄悄排掉了大部分交错——GPU 上没有这个兜底，交错落谁家由调度顺序决定。第三，数千线程共享一个输出流，「printf 顺序」四个字没有定义。不承认这三条的调试，通常是改一版、跑一遍、碰运气。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>错误传播的纪律先立起来：每个运行时 API 调用后查返回码；kernel 之后用 <code>cudaGetLastError</code> 加 <code>cudaDeviceSynchronize</code> 把异步错误拉回调用点。注意 sticky error：一次非法访存之后整个上下文带病，后续调用连环失败，报错位置与真实现场相距甚远——先把「第一次失败」找出来，必要时 <code>cudaDeviceReset</code> 清场重来。cuda-gdb 的视角是 warp 级：断点打到 kernel 行，<code>focus</code> 在 thread、warp、lane 之间切换，看的是单个 lane 的寄存器与变量；「切换 focus」这个动作本身就是 SIMT 语义的调试版——同一断点上 32 个 lane 一起停，各自的状态分别可查。printf 的语义要背下来：每线程一条缓冲，kernel 结束或显式 flush 时统一吐出——它当示波器用（确认某 lane 某时刻的值），不当日志用（顺序与完备性都没有承诺）。</p>',7)),(E(),A(n,null,{default:a(()=>[t(i,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUG%5B%22%E9%94%99%E8%AF%AF%EF%BC%9A%E6%95%B0%E5%80%BC%E4%B8%8D%E5%AF%B9%20%2F%20%E5%B4%A9%E6%BA%83%22%5D%20--%3E%20SYNC%5B%22%E5%90%8C%E6%AD%A5%E6%8B%89%E5%9B%9E%EF%BC%9A%E8%BF%94%E5%9B%9E%E7%A0%81%20%2B%20cudaDeviceSynchronize%22%5D%0A%20%20SYNC%20--%3E%20FIRST%5B%22%E5%AE%9A%E4%BD%8D%E7%AC%AC%E4%B8%80%E6%AC%A1%E5%A4%B1%E8%B4%A5%EF%BC%8C%E8%AD%A6%E6%83%95%20sticky%20error%22%5D%0A%20%20FIRST%20--%3E%20MEM%7B%22%E7%97%87%E7%8A%B6%E6%98%AF%E8%AE%BF%E9%97%AE%E8%B6%8A%E7%95%8C%EF%BC%9F%22%7D%0A%20%20MEM%20--%3E%7C%E6%98%AF%7C%20MC%5B%22compute-sanitizer%20memcheck%20%2F%20initcheck%22%5D%0A%20%20MEM%20--%3E%7C%E5%90%A6%EF%BC%8C%E9%97%B4%E6%AD%87%E6%80%A7%7C%20RACE%7B%22%E4%B8%8E%20warp%20%E4%BA%A4%E9%94%99%E6%9C%89%E5%85%B3%EF%BC%9F%22%7D%0A%20%20RACE%20--%3E%7C%E6%98%AF%7C%20RC%5B%22racecheck%EF%BC%9Asmem%20%E7%9A%84%20RAW%20%2F%20WAR%20%2F%20WAW%22%5D%0A%20%20RACE%20--%3E%7C%E5%90%A6%7C%20GDB%5B%22cuda-gdb%EF%BC%9Afocus%20%E5%88%B0%20lane%EF%BC%8C%E5%8D%95%E6%AD%A5%E6%9F%A5%E5%80%BC%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>sanitizer 为什么必须独立成工具：竞态检测要看见「所有可能的交错」，而调度顺序不可复现，唯一可靠的办法是插桩执行——把每次 smem 访问记录下来，按读写序找 hazard。racecheck 报告分 RAW、WAR、WAW 三类，对着屏障语义读：WAR 多半是双缓冲少了第二道屏障，上一轮的读还没完就被下一轮的写覆盖；这类错误 profile 完全看不见，因为结果是「有时对」。四件套各管一摊：memcheck 查全局越界与对齐、initcheck 查未初始化读、synccheck 查屏障误用（发散调用、配对缺失）。代价是插桩减速一到两个数量级——定位用它，回归测试别全量跑，挑风险内核定时跑。</p><p>确定性是复现的前提：warp 调度顺序无承诺，把随机种子、launch 配置、输入数据钉死，缩小到能触发问题的最小形状，竞态才有得治。驱动层的崩溃另有体系：Xid 编码表把 GPU 侧异常分类（非法访存、ECC、掉卡），先查表再猜——驱动报的错误码比应用程序的二次转述可信。</p><p><span class="marginnote">术语翻译：sticky error 就是「一次犯罪，终身记录」——非法访存让整个 CUDA 上下文进入带病状态，之后所有 API 调用都返回同一种错误，哪怕那些调用本身毫无问题。所以报错的那一行几乎一定不是真凶；正确动作是 <code>cudaDeviceReset</code> 清场，从头二分定位第一次失败。</span></p><p><span class="marginnote">数字实例：<code>compute-sanitizer</code> 插桩减速一到两个数量级——一个正常跑 10 秒的内核，memcheck 下可能要跑 10 分钟以上。全量回归测试跑不起，工程上的做法是：CI 平时只跑快测试，每晚或每次改动同步逻辑时对高风险内核定向跑一遍四件套。</span></p>',5)),(E(),A(n,null,{default:a(()=>[t(i,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20E%5B%22%E5%BC%82%E6%AD%A5%E9%94%99%E8%AF%AF%E6%B5%AE%E5%87%BA%22%5D%20--%3E%20W%7B%22%E6%8A%A5%E9%94%99%E7%82%B9%E7%AD%89%E4%BA%8E%E4%BA%8B%E5%8F%91%E7%82%B9%3F%22%7D%0A%20%20W%20--%3E%7C%22%E6%98%AF%20%E7%BD%95%E8%A7%81%22%7C%20FIX%5B%22%E5%8E%9F%E5%9C%B0%E4%BF%AE%22%5D%0A%20%20W%20--%3E%7C%22%E5%90%A6%20%E5%B8%B8%E8%A7%81%22%7C%20RESET%5B%22cudaDeviceReset%20%E6%B8%85%E5%9C%BA%22%5D%0A%20%20RESET%20--%3E%20BIS%5B%22%E9%92%89%E6%AD%BB%E7%A7%8D%E5%AD%90%E4%B8%8E%E9%85%8D%E7%BD%AE%0A%20%20%E4%BA%8C%E5%88%86%E7%BC%A9%E5%B0%8F%E5%88%B0%E6%9C%80%E5%B0%8F%E5%A4%8D%E7%8E%B0%22%5D%0A%20%20BIS%20--%3E%20SAN%5B%22sanitizer%20%E6%8F%92%E6%A1%A9%E5%8F%96%E8%AF%81%22%5D%0A%20%20SAN%20--%3E%20ROOT%5B%22%E6%89%BE%E5%88%B0%E7%AC%AC%E4%B8%80%E6%AC%A1%E5%A4%B1%E8%B4%A5%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[c(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>多 GPU 一致性与 NVLink 级问题、驱动与固件的深水区，不在本课——那要系统层的取证。性能问题回上一课的 profiler，别拿 sanitizer 找慢：插桩本身改变时序，测出来的「性能」没有意义。printf 与断点都有观察者效应（串行化、重排），确认问题存在之后，定位要靠 sanitizer 的插桩证据，而不是更多打印。最后，调试纪律的尽头是少调试：把布局合同（第五课的 lane 映射表）写成断言、把同步配对写成 RAII 封装，让错误在编译期和第一次运行就现形。</p><p><span class="marginnote">racecheck 的易错点：它只查 smem，不查全局内存——全局的竞态要靠原子与内存序（acquire-release 那套合同）自证，工具只能提示可疑访问对。两类存储、两套检查手段，别混着期待。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>异步 launch 与 sticky error 决定错误传播纪律：每个调用点查码，同步拉回，先找第一次失败。</li><li>smem 无一致性兜底，竞态按交错随机出现；复现先钉死种子、配置与输入。</li><li>printf 是示波器不是日志：缓冲统一吐出，顺序无承诺。</li><li>compute-sanitizer 四件套对四类病：memcheck、racecheck、initcheck、synccheck；插桩减速一到两个量级。</li><li>racecheck 只管 smem；全局内存的竞态归原子与内存序。</li><li>出处：NVIDIA CUDA 工具链文档（cuda-gdb、compute-sanitizer）与驱动 Xid 编码表。</li></ul>',5))])}const F=s(B,[["render",d]]);export{_ as __pageData,F as default};
